from pathlib import Path
from html import escape
import json, hashlib, base64

ROOT = Path(__file__).parent
NOTE = 'Pinterest Alternatives — Visual Research and Moodboarding.md'
HTML = 'Pinterest Alternatives — Visual Research and Moodboarding.html'
DATE = '2026-10-13'
COVER = Path('/home/ivanaguilera/Documents/Obsidian Vault/Attachments/The Portrait Edit - Issue 01/study-02-reference.jpg')
# name, category, region, official URL, editorial use, access/context, verification URL
ROWS = [
 ('Cosmos','Collect & organize','Global','https://www.cosmos.so/','Visual discovery, color-led searches and project collections. Start here for a Pinterest-like browsing experience.','Account for collecting. Offers controls to show, blur or hide images flagged as AI-generated.','https://www.cosmos.so/'),
 ('Are.na','Collect & organize','Global','https://www.are.na/','Connect images, text and links in channels; useful for concept research with written context.','Account for saving. Channels connect ideas; original image provenance still needs checking.','https://www.are.na/about'),
 ('Raindrop.io','Collect & organize','Global','https://raindrop.io/','Keep source URLs organized by collection and tag, alongside your credit records.','Free and paid plans. Check plan requirements for preservation and advanced features.','https://raindrop.io/'),
 ('Milanote','Collect & organize','Global','https://milanote.com/','Arrange images, notes and links into an editorial moodboard or shoot brief.','Account required for boards. Check current limits before committing a large project.','https://milanote.com/'),
 ('FigJam','Collect & organize','Global','https://www.figma.com/figjam/','Build a shared canvas for image grouping, annotations and collaborative decisions.','Figma account for editing; a whiteboard rather than a fashion discovery feed.','https://www.figma.com/figjam/'),
 ('PureRef','Collect & organize','Global','https://www.pureref.com/','Arrange your own reference images on a focused desktop canvas. Recommended local option for this Linux setup.','Supports Windows, macOS and Linux. Provides a workspace for references rather than a source catalogue.','https://www.pureref.com/'),
 ('Eagle','Collect & organize','Global','https://en.eagle.cool/','Manage a large local collection with tags, folders and visual search.','Official downloads list Windows and macOS; no native Linux download was listed.','https://en.eagle.cool/'),
 ('Linkwarden','Collect & organize','Global','https://linkwarden.app/','Collect links and preserve pages; useful when the underlying article may change.','Hosted service or self-hosting. Login pages and dynamic media may need special handling; verify each saved page.','https://linkwarden.app/'),
 ('Shaarli','Collect & organize','Global','https://github.com/shaarli/Shaarli','Keep a lightweight, self-hosted bookmark archive with descriptions and tags.','Technical setup required. A link archive rather than a polished image discovery platform.','https://github.com/shaarli/Shaarli'),
 ('FASHIONSNAP','Fashion references','Japan','https://www.fashionsnap.com/streetstyle/','Study documented street outfits, layering and brand details across Tokyo and other Japanese cities.','Japanese interface. Use snap dates and photographer credits when selecting references.','https://www.fashionsnap.com/streetstyle/'),
 ('Tokyo Fashion','Fashion references','Japan','https://tokyofashion.com/photos/','Explore Harajuku, Shibuya and Japanese subculture silhouettes through street photography.','Includes archival material. Check each photo’s date before describing it as a 2025–2026 trend.','https://tokyofashion.com/photos/'),
 ('MUSINSA Snap','Fashion references','South Korea','https://www.musinsa.com/snap/main/recommend','Compare Korean daily outfits using the current Snap interface and styling categories.','Korean interface with dynamic content. Commercial and creator styling is not a representative population sample.','https://www.musinsa.com/snap/main/recommend'),
 ('Vogue Korea','Fashion references','South Korea','https://www.vogue.co.kr/','Research Korean fashion editorial direction, styling and local fashion coverage.','Korean-language publication. Separate editorials and celebrity looks from everyday streetwear.','https://www.vogue.co.kr/'),
 ('Vogue China','Fashion references','China','https://www.vogue.com.cn/','Explore Chinese fashion editorials, designer coverage and magazine art direction.','Chinese-language publication. Save the specific article, date and photo credit.','https://www.vogue.com.cn/'),
 ('Dewu / 得物','Fashion references','China','https://www.dewu.com/','Explore a Chinese commerce-and-community platform for streetwear and outfit ideas.','Official site confirms a community entry point and app downloads; full community browsing was not tested.','https://www.dewu.com/'),
 ('Xiaohongshu / 小红书','Fashion references','China','https://www.xiaohongshu.com/','Search creator styling and garment vocabulary such as 新中式穿搭 and 马面裙穿搭.','Retained from the original shortlist. Automated access failed; login requirements and current search features were not verified.','https://www.xiaohongshu.com/'),
 ('Jing Daily','Fashion references','China','https://jingdaily.com/','Add reporting and market context to a China-focused visual board.','Some reporting is subscription content. An article’s trend claim needs its own evidence.','https://jingdaily.com/'),
 ('Vogue Runway','Fashion references','Global','https://www.vogue.com/fashion-shows','Compare designer collections by season, garment shape and styling.','Subscription prompts appear. Runway images describe collections, not everyday adoption.','https://www.vogue.com/fashion-shows'),
 ('Tagwalk','Fashion references','Global','https://www.tag-walk.com/en/','Research runway looks, collections and styling vocabulary; useful for comparing silhouettes.','Account and premium sections exist. Check feature access; reports and runway signals have a different scope from street fashion.','https://www.tag-walk.com/en/'),
 ('nss magazine','Fashion references','Global','https://www.nssmag.com/en/fashion','Explore fashion-week street photography, culture and editorial references.','Open the dated gallery, not just the feed. Coverage varies by event and city.','https://www.nssmag.com/en/fashion'),
 ('Dazed','Fashion references','Global','https://www.dazeddigital.com/fashion','Study experimental styling, youth culture and fashion editorial treatments.','Distinguish editorial, sponsored and documentary material.','https://www.dazeddigital.com/fashion'),
 ('SHOWstudio','Fashion references','Global','https://www.showstudio.com/','Study fashion film, performance and illustration when developing motion or shoot direction.','Main site blocked automated retrieval. Official gallery page supports the fashion-film and illustration focus; playback was not tested.','https://shop.showstudio.com/pages/about-show-gallery'),
 ('Vestiaire Collective','Fashion references','Global','https://www.vestiairecollective.com/','Inspect resale listings for garment details, construction and vintage styling clues.','Seller descriptions and dates need cross-checking; inventory changes and photos are not a trend sample.','https://www.vestiairecollective.com/'),
 ('Designspiration','Design & art direction','Global','https://www.designspiration.com/','Explore visual ideas for palette, typography and photographic treatments.','JavaScript required; saving uses an account. Trace collected images to their original creator.','https://www.designspiration.com/'),
 ('Behance','Design & art direction','Global','https://www.behance.net/','Study creative portfolios for magazine grids, branding, photography and presentation systems.','Official help page verified; homepage retrieval failed. Projects demonstrate an author’s design approach.','https://help.behance.net/hc/en-us/articles/204483894-What-is-Behance'),
 ("It’s Nice That",'Design & art direction','Global','https://www.itsnicethat.com/','Find designer and photographer stories to inform editorial typography and visual direction.','Use the article’s named studio or artist as the next research step.','https://www.itsnicethat.com/'),
 ('V&A Fashion','Archives & textiles','Global','https://www.vam.ac.uk/collections/fashion','Research historical garment forms, construction and collection context.','Historical collection evidence, not a current-trend feed. Check item dates and image-use terms.','https://www.vam.ac.uk/collections/fashion'),
 ('Europeana Textile','Archives & textiles','Global','https://www.europeana.eu/en/collections/topic/55-textile','Explore textile and dress references across European cultural collections.','Rights and metadata vary by item and contributing institution. Use the individual record.','https://www.europeana.eu/en/collections/topic/55-textile'),
]
CATEGORIES = ['Collect & organize','Fashion references','Design & art direction','Archives & textiles']
SHORTLIST = [('China','Vogue China + Jing Daily','Dewu or Xiaohongshu for creator leads; verify the original post and date.'),('Japan','FASHIONSNAP + Tokyo Fashion','Compare current snaps with dated subculture archives.'),('South Korea','MUSINSA Snap + Vogue Korea','Compare daily styling with editorial interpretation.'),('Your working collection','Cosmos or Are.na + Raindrop.io','Collect visually, keep a source record, then bring the final selection into Obsidian.')]

def build():
    out=ROOT/'staged';out.mkdir(exist_ok=True)
    logos={item['name']:item for item in json.loads((ROOT/'logos-manifest.json').read_text())}
    assert all('file' in logos[row[0]] for row in ROWS)
    def logo_html(name):
        asset=logos[name]
        encoded=base64.b64encode((ROOT/'logos'/asset['file']).read_bytes()).decode()
        return f'<img class="brand-logo" src="data:{asset["mime"]};base64,{encoded}" alt="{escape(name)} logo" width="48" height="48">'
    md=['---','tags: [visual-research, moodboarding, fashion]','updated: '+DATE,'---','','# Pinterest Alternatives — Visual Research & Moodboarding','',f'**Research directory · Updated {DATE} · {len(ROWS)} sources and tools**','',
        'A practical directory for discovering fashion references, developing magazine art direction, and keeping a traceable visual library. The recommended workflow starts with sources for China, Japan and South Korea, then brings selected references into a collection tool and Obsidian.','',
        f'[[Attachments/Pinterest Alternatives/{HTML}|Open the designed HTML directory]] · [[Asia Fashion — Visual Guide/Fashion Visual Companion|Asia Fashion Visual Companion]]','',
        '> [!tip] Suggested starting setup\n> Browse **Cosmos** for visual discovery or **Are.na** for concept research; keep original URLs in **Raindrop.io**. Use **PureRef** for a local Linux reference canvas. These are editorial recommendations, not a claim that one tool replaces every Pinterest feature.','',
        '## Start with the Asia-fashion shortlist','','| Focus | Start here | Next step |','| --- | --- | --- |']
    for row in SHORTLIST:md.append('| '+' | '.join(row)+' |')
    md += ['','## Source directory','','Official pages were checked on '+DATE+'. A successful page check does not confirm logged-in features, subscriptions, exports or offline saving. Access limits are recorded below; prices are intentionally omitted.','']
    for cat in CATEGORIES:
        md += ['### '+cat,'','| Logo | Source | Region | Use in your project | Access / context |','| --- | --- | --- | --- | --- |']
        for name,category,region,url,use,access,proof in ROWS:
            if category==cat:md.append(f'| ![[Attachments/Pinterest Alternatives/logos/{logos[name]["file"]}\\|28]] | [{name}]({url}) | {region} | {use} | {access}'+(f' [Official context]({proof}).' if proof!=url else '')+' |')
        md += ['']
    workflow=[('Define the visual question','Choose one subject per board: a silhouette, fabric, styling detail, palette or page treatment.'),('Collect with context','Save the original page or creator post, image credit, publication date, country/city, and the styling detail you want to study.'),('Compare references','Use several independent examples. Keep runway, street photography, product listings, historical objects and AI interpretations visibly separate.'),('Build the board','Group by silhouette, material, palette and accessory. Add a sentence explaining each selection instead of collecting lookalikes without context.'),('Keep the final record in Obsidian','Store permitted local copies with the source record; revisit the original page before publication. A collection link alone is not a durable backup.')]
    md += ['## A repeatable research workflow','']
    for i,(title,body) in enumerate(workflow,1):md.append(f'{i}. **{title}.** {body}')
    md += ['','### Reference record template','','```text','Reference ID:','Board / visual question:','Country / city:','Garment or styling detail:','Source type: street photo / runway / editorial / product / archive / AI','Original page URL:','Creator / photographer / publication:','Published / collection date:','Retrieved:','Local attachment, if permitted:','Image-use terms / permission status:','Why this reference matters:','```','',
        '### Useful search vocabulary','','These are suggested search phrases, not verified trend rankings.','',
        '| Market | Suggested phrases |','| --- | --- |','| China | 新中式穿搭 (new Chinese-style outfits); 马面裙穿搭 (mamianqun styling); 户外穿搭 (outdoor styling) |','| Japan | ストリートスナップ (street snaps); 古着 コーデ (vintage outfits); レイヤード (layering) |','| South Korea | 데일리룩 (daily looks); 아쿠비 (Acubi); 한복 스타일링 (hanbok styling) |','',
        '## Rechecked from the earlier shortlist','',
        '- **[We Heart It](https://weheartit.com/): keep as a legacy lead, not a recommended starting tool.** Its retrieved public homepage showed support/legal links rather than a usable discovery or board interface. This does not prove that every app or account feature is unavailable.','- **Are.na:** channels can preserve your organization, but external sources can still change or disappear. The earlier “no pin rot” claim was too strong.','- **Dewu and Xiaohongshu:** removed the unsupported “best” and “strongest” rankings. Their usefulness depends on accessible posts, language and source verification.','- **Shaarli:** the official GitHub repository remains the reliable project reference here; the earlier claim about another domain’s TLS certificate was not reverified.','- **Pinterest links:** availability and hotlink behavior vary. Keep provenance and permitted local copies rather than assuming every link will fail.','',
        '## Publication and verification notes','',
        'Links support discovery and research; they do not grant magazine reproduction rights. Record the individual image’s terms or permission status. Native app access, login flows, subscription features and installations were not tested. No accounts were created and no collection service was connected.','',
        'The existing reference-credit convention (`images/references/CREDITS.md`) can be reused if that file exists in the project; no new credit ledger was populated by this directory update.','']
    md.insert(md.index('## Start with the Asia-fashion shortlist'), '![[Attachments/The Portrait Edit - Issue 01/study-02-reference.jpg|520]]\n\n*Cover reference from The Portrait Edit — Issue 01.*\n')
    (out/NOTE).write_text('\n'.join(md))
    cards=[]
    for i,(name,cat,region,url,use,access,proof) in enumerate(ROWS,1):
        context=f'<a class="context-link" href="{escape(proof)}" target="_blank" rel="noopener">Official context ↗</a>' if proof!=url else ''
        cards.append(f'<article class="source" data-category="{escape(cat)}" data-region="{escape(region)}"><div class="brand-row">{logo_html(name)}<div class="card-meta"><span>{i:02}</span><span>{escape(region)}</span></div></div><p class="category">{escape(cat)}</p><h3><a href="{escape(url)}" target="_blank" rel="noopener">{escape(name)} <span aria-hidden="true">↗</span></a></h3><p>{escape(use)}</p><div class="access"><strong>Before you use it</strong><p>{escape(access)}</p>{context}</div></article>')
    shortlist=''.join(f'<div><span>{escape(a)}</span><h3>{escape(b)}</h3><p>{escape(c)}</p></div>' for a,b,c in SHORTLIST)
    steps=''.join(f'<li><h3>{escape(a)}</h3><p>{escape(b)}</p></li>' for a,b in workflow)
    filters=''.join(f'<button type="button" data-filter="{escape(c)}" aria-pressed="false">{escape(c)}</button>' for c in CATEGORIES)
    css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f7f5ef;color:#252821;font:16px/1.65 Arial,sans-serif}a{color:inherit;text-underline-offset:4px}button,input,select{font:inherit}button,a,input,select{outline-offset:4px}main{max-width:1420px;margin:auto;padding:0 5vw}.masthead{display:flex;justify-content:space-between;padding:22px 0;border-bottom:1px solid #bbbdb2;font-size:11px;letter-spacing:.14em}.hero{padding:60px 0 42px;display:grid;grid-template-columns:1.5fr 1fr;gap:60px}.eyebrow,.category,.card-meta,.section-top>span{font-size:11px;text-transform:uppercase;letter-spacing:.12em;color:#5a6656}h1,h2,h3{font-family:Georgia,serif;font-weight:normal}h1{font-size:clamp(48px,7vw,86px);line-height:1.02;letter-spacing:-.045em;margin:18px 0 25px}h2{font-size:42px;line-height:1.15;margin:10px 0 18px}h3{font-size:24px;line-height:1.25;margin:14px 0}.hero p{max-width:650px}.hero aside{align-self:end;border-top:3px solid #bd532e;padding:24px 0}.hero aside strong{font:72px/1 Georgia,serif}.hero aside p{color:#60685b}.jump{display:flex;gap:24px;flex-wrap:wrap;font-size:13px;padding-bottom:32px}section{border-top:1px solid #b9beaf;padding:40px 0}.shortlist{display:grid;grid-template-columns:repeat(4,1fr);gap:26px}.shortlist>div{border-top:2px solid #bd532e;padding-top:20px}.shortlist span{font-size:12px;color:#5a6656}.shortlist h3{font-size:22px}.shortlist p{font-size:14px}.controls{display:flex;gap:12px;margin:28px 0 18px;flex-wrap:wrap}.controls input{flex:1;min-width:220px}.controls input,.controls select{background:white;border:1px solid #b9beaf;padding:12px}.filters{display:flex;gap:8px;flex-wrap:wrap}.filters button{border:1px solid #b9beaf;border-radius:24px;background:transparent;padding:8px 15px;font-size:12px;cursor:pointer}.filters button[aria-pressed=true]{background:#283b30;color:white;border-color:#283b30}.count{font-size:12px;color:#60685b}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}.source{background:#fffefb;border:1px solid #d6d8cd;padding:24px;display:flex;flex-direction:column}.card-meta{display:flex;justify-content:space-between}.source .category{margin:22px 0 0}.source h3 a{text-decoration:none;display:flex;justify-content:space-between;gap:15px}.source h3 a:hover{text-decoration:underline}.source>p{font-size:14px}.access{margin-top:auto;border-top:1px solid #e1e2d9;padding-top:18px;font-size:12px;color:#5e6658}.access strong{font-size:10px;letter-spacing:.08em;text-transform:uppercase}.access p{margin:8px 0}.context-link{font-size:11px}.workflow{display:grid;grid-template-columns:repeat(2,1fr);gap:22px;list-style:decimal-leading-zero;padding-left:28px}.workflow li{padding-left:8px}.workflow li::marker{color:#bd532e}.workflow p{font-size:14px}.notes{display:grid;grid-template-columns:1fr 1fr;gap:34px}.notes p,.notes li{font-size:14px}.record{background:#e9ede3;padding:24px;border-left:3px solid #536747;white-space:pre-wrap;font-size:12px}.section-top p{max-width:800px;color:#60685b;font-size:14px}footer{padding:30px 0;border-top:1px solid #b9beaf;font-size:11px;color:#60685b}[hidden]{display:none!important}@media(max-width:1000px){.grid{grid-template-columns:repeat(2,1fr)}.shortlist{grid-template-columns:repeat(2,1fr)}.hero{gap:30px}}@media(max-width:650px){.hero{grid-template-columns:1fr;gap:15px;padding-top:35px}.hero aside{display:none}.grid,.shortlist,.workflow,.notes{grid-template-columns:1fr}.masthead span:last-child{display:none}h2{font-size:34px}.source{padding:22px}}@media print{.controls,.filters,.jump{display:none}.source{break-inside:avoid}.grid{grid-template-columns:repeat(2,1fr)}[hidden]{display:flex!important}}'''
    css += '''.brand-row{display:flex;align-items:center;gap:18px}.brand-row .card-meta{flex:1}.brand-logo{display:block;flex:none;width:48px;height:48px;object-fit:contain;background:white;border:1px solid #e1e2d9;border-radius:10px;padding:6px}'''
    css += '''.hero{grid-template-columns:1fr 1fr;gap:54px;align-items:center;padding:44px 0}.hero h1{font-size:clamp(64px,7.5vw,108px)}.hero aside{align-self:stretch;border:0;padding:0;margin:0}.cover-image{margin:0;height:100%}.cover-image img{display:block;width:100%;height:auto;aspect-ratio:1280/1626;object-fit:contain}.cover-image figcaption{font-size:10px;letter-spacing:.1em;text-transform:uppercase;margin-top:12px;color:#667060}.cover-kicker{display:flex;gap:22px;flex-wrap:wrap;border-top:1px solid #b9beaf;margin-top:30px;padding-top:18px;font-size:11px;letter-spacing:.07em;text-transform:uppercase}.cover-line{font-family:Georgia,serif;font-size:26px;line-height:1.25;margin-top:30px}.masthead span:first-child{font-family:Georgia,serif;font-size:24px;letter-spacing:.05em;color:#252821}.masthead{align-items:center}.jump{padding-top:8px}@media(max-width:650px){.hero{grid-template-columns:1fr;gap:28px}.hero aside{display:block}.hero h1{font-size:72px}.cover-image{max-width:440px;margin:auto}.masthead span:first-child{font-size:19px}.cover-line{font-size:23px}}'''
    cover_data='data:image/jpeg;base64,'+base64.b64encode(COVER.read_bytes()).decode()
    script='''const cards=[...document.querySelectorAll('.source')];let category='All';const search=document.querySelector('#search'),region=document.querySelector('#region');function update(){let n=0;const q=search.value.trim().toLocaleLowerCase();cards.forEach(c=>{const show=(category==='All'||c.dataset.category===category)&&(region.value==='All'||c.dataset.region===region.value)&&c.textContent.toLocaleLowerCase().includes(q);c.hidden=!show;if(show)n++;});document.querySelector('#count').textContent=n+' of '+cards.length+' sources';document.querySelector('#empty').hidden=n!==0;}document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{category=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));update();}));search.addEventListener('input',update);region.addEventListener('change',update);update();'''
    record='Reference ID\nBoard / visual question\nCountry / city\nGarment or styling detail\nSource type\nOriginal page URL\nCreator / photographer / publication\nPublished / collection date\nRetrieved\nLocal attachment, if permitted\nImage-use terms / permission status\nWhy this reference matters'
    html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pinterest Alternatives — Visual Research and Moodboarding</title><style>{css}</style></head><body><main><div class="masthead"><span>THE VISUAL EDIT</span><span>UPDATED 13 OCTOBER 2026</span></div><header class="hero"><div><div class="eyebrow">The inspiration issue / No. 01</div><h1>Beyond<br>Pinterest.</h1><p class="cover-line">Collect with intention.<br>Develop your visual point of view.</p><p>A considered directory for fashion references, magazine art direction and moodboarding. Curated for your China, Japan and South Korea research.</p><div class="cover-kicker"><span>{len(ROWS)} sources &amp; tools</span><span>China / Japan / Korea</span><span>Research edition</span></div></div><aside><figure class="cover-image"><img src="{cover_data}" alt="Portrait reference from The Portrait Edit, Issue 01" width="1280" height="1626"><figcaption>The Portrait Edit / Study 02 · Cover reference</figcaption></figure></aside></header><nav class="jump" aria-label="Sections"><a href="#shortlist">Start here</a><a href="#directory">Source directory</a><a href="#workflow">Research workflow</a><a href="#notes">Access & context</a></nav><section id="shortlist"><div class="section-top"><span>01 / EDITOR’S SHORTLIST</span><h2>A practical starting point.</h2><p>These pairings are editorial recommendations. Choose the source for the question you are researching, then save the original reference with context.</p></div><div class="shortlist">{shortlist}</div></section><section id="directory"><div class="section-top"><span>02 / THE DIRECTORY</span><h2>Find the right reference.</h2><p>Browse sources, collection tools, design publications and historical archives. Official pages checked {DATE}; access and feature limits are noted on each card.</p></div><div class="controls"><input id="search" type="search" aria-label="Search sources" placeholder="Search sources, silhouettes, tools…"><select id="region" aria-label="Filter region"><option>All</option><option>China</option><option>Japan</option><option>South Korea</option><option>Global</option></select></div><div class="filters" aria-label="Filter category"><button type="button" data-filter="All" aria-pressed="true">All sources</button>{filters}</div><p id="count" class="count" aria-live="polite">{len(ROWS)} sources</p><p id="empty" hidden>No sources match. Try another term or reset the filters.</p><div class="grid">{''.join(cards)}</div></section><section id="workflow"><div class="section-top"><span>03 / FROM DISCOVERY TO DIRECTION</span><h2>Build a board with a purpose.</h2></div><ol class="workflow">{steps}</ol></section><section id="notes"><div class="section-top"><span>04 / THE RESEARCH RECORD</span><h2>Keep the context.</h2></div><div class="notes"><div><h3>One record for each reference.</h3><p>Use this structure in Obsidian or your bookmark manager. A useful board explains what each image contributes.</p><pre class="record">{record}</pre></div><div><h3>Access & publication.</h3><p>Source links do not grant image reproduction rights. Record the individual item’s terms or permission status before magazine publication. Login flows, paid features, offline saving and native apps were not tested.</p><h3>What changed from the first list.</h3><p><a href="https://weheartit.com/" target="_blank" rel="noopener">We Heart It</a> stays a legacy lead: its retrieved public page did not expose a usable discovery interface. This does not establish the status of every app or account feature.</p><p>Are.na does not guarantee that external sources will remain available. Dewu and Xiaohongshu are useful leads, but the earlier “best” rankings were unsupported. Shaarli’s GitHub page is retained; the earlier certificate claim was not rechecked.</p><h3>Search in the source language.</h3><p>China: 新中式穿搭 · 马面裙穿搭<br>Japan: ストリートスナップ · 古着 コーデ<br>Korea: 데일리룩 · 아쿠비 · 한복 스타일링</p><p>Suggested search phrases, not measured trend rankings.</p></div></div></section><footer>RESEARCH EDITION / {DATE} · This directory works offline; external sources require internet. No accounts created or services connected. Links lead to official sources; each reference needs its own date, credit and context.</footer></main><script>{script}</script></body></html>'''
    (out/HTML).write_text(html)
    (ROOT/'sources.json').write_text(json.dumps([dict(zip(['name','category','region','url','use','access','verification_url'],row)) for row in ROWS],ensure_ascii=False,indent=2))
    (ROOT/'original.sha256').write_text(hashlib.sha256((ROOT/'original.md').read_bytes()).hexdigest())
    assert html.count('class="source"')==len(ROWS)
    assert len({r[0] for r in ROWS})==len(ROWS)
    print(f'Built Markdown and searchable HTML with {len(ROWS)} sources and tools.')

if __name__=='__main__':build()
